Combining Multiple Years
The single-year function can be extended to compare Census data across multiple survey years. The following function allows the user to select multiple years and combines the results into one tibble.

get_census_years &lt;- function(
    years = 2021:2024,
    numeric_vars = c("AGEP", "PWGTP"),
    categorical_vars = "SEX",
    geography = "State",
    geo_value = NULL
) {
  #Allow user to select all years
  if (length(years) == 1 && tolower(as.character(years)) == "all") {
    years &lt;- 2021:2024
  }

  #Check years
  if (!all(years %in% 2021:2024)) {
    stop("years must be 2021/2022/2023/2024 or all")
  }

  #Empty list to store each year
  census_list &lt;- list()

  #Get data from each year
  for (year in years) {

    census_list[[as.character(year)]] &lt;- get_census_data(
      year = year,
      numeric_vars = numeric_vars,
      categorical_vars = categorical_vars,
      geography = geography,
      geo_value = geo_value
    )

    #Add year variable
    census_list[[as.character(year)]]$year &lt;- factor(year)
  }

  #Combine years into one tibble
  census_data &lt;- bind_rows(census_list)

  #Add census class
  if (!inherits(census_data, "census")) {
    class(census_data) &lt;- c("census", class(census_data))
  }

  return(census_data)
}


