Querying Single-Year Census Data
Next, we implement functions to query single-year PUMS data and convert the response into a tibble. The function allows users to select between numeric, categorical, and geographic variables.

First helper API response\(\to\)tibble

response_to_tibble &lt;- function(response) {

  #Parse JSON response
  census_data &lt;- content(
    response,
    as = "text",
    encoding = "UTF-8"
  ) |&gt;
    fromJSON()

  #First row contains variable names
  variable_names &lt;- census_data[1,]

  #Remaining rows are observation values
  census_data &lt;- census_data[-1, , drop = FALSE]

  #Add variable names
  colnames(census_data) &lt;- variable_names

  #Convert to tibble
  census_data &lt;- as_tibble(census_data)

  census_data
}



Second helper Census time interval \(\to\) midpoint

#Convert Census time interval to midpoint
time_midpoint &lt;- function(time_interval) {

  #Return NA for missing values or non-time values
  if (
    is.na(time_interval) ||
    length(time_interval) == 0 ||
    !grepl(" to ", time_interval)
  ) {
    return(NA)
  }

  #Split beginning and ending times
  times &lt;- strsplit(time_interval, " to ")[[1]]

  #Remove periods from a.m and p.m.
  times &lt;- gsub("\\.", "", times)

  #Convert to times
  start_time &lt;- parse_date_time(times[1], "I:M p")
  end_time &lt;- parse_date_time(times[2], "I:M p")

  #Calculate midpoint
  midpoint &lt;- start_time + ((end_time - start_time) / 2)

  return(midpoint)
}



Third helper to retrieve census data

#API Key is now required to access Census data
census_api_key &lt;- Sys.getenv("CENSUS_API_KEY")
get_census_data &lt;- function(
    year = 2024,
    numeric_vars = c("AGEP", "PWGTP"),
    categorical_vars = "SEX",
    geography = "State",
    geo_value = NULL,
    key = census_api_key
) {

  #Allowed variables
  allowed_numeric &lt;- c("AGEP", "GASP", "GRPIP", "JWAP", "JWDP", "JWMNP", "PWGTP")

  allowed_categorical &lt;- c("FER", "HHL", "SCH", "SCHL", "SEX")

  allowed_geography &lt;- c("Region", "Division", "State")

  #Check year
  if (length(year) != 1 || !year %in% 2021:2024) {
    stop("Year must be 2021/2022/2023/2024")
  }

  #Check numeric variables
  if (!all(numeric_vars %in% allowed_numeric)) {
    stop("Invalid numeric variable")
  }

  if (!"PWGTP" %in% numeric_vars) {
    stop("PWGTP must be included as a numeric variable")
  }

  if (length(setdiff(numeric_vars, "PWGTP"))&lt;1) {
    stop("At least one numeric variable besides PWGTP must be selected")
  }

  #Check categorical variables
  if (length(categorical_vars) &lt; 1 || !all(categorical_vars %in% allowed_categorical)) {
    stop("At least one valid categorical variable must be selected")
  }
  #Check geography
  if (length(geography) != 1 || !geography %in% allowed_geography) {
    stop("Geography must be Region, Division, or State")
  }

  #Read variable metadata
  variable_info &lt;- readRDS("data/census_variables.rds")[[as.character(year)]]

  #Determine Census geography variable
  geo_var &lt;- if (geography == "State") {
    if (year &lt;= 2022) "ST" else "STATE"
  } else {
    toupper(geography)
  }

  #Obtain allowable geography values
  geo_values &lt;- variable_info[[geo_var]]$values$item

  #Use first available geography as default
  if (is.null(geo_value)) {
    geo_value &lt;- names(geo_values)[1]
  }

  #Check selected geography value
  if (tolower(geo_value) != "all" &&
      !geo_value %in% names(geo_values)) {
    stop("Invalid geography value selected")
  }

  #Variables requested from API
  selected_vars &lt;- unique(c(numeric_vars, categorical_vars))

  #Create Census API URL
  url &lt;- paste0("https://api.census.gov/data/",
  year,
  "/acs/acs1/pums"
  )

  #Allow one geography value or all values
  if(tolower(geo_value) == "all") {
    geography_query &lt;- "*"
  } else {
    geography_query &lt;- geo_value
  }

  #Query Census API
  response &lt;- GET(url, query = list(
    get = paste(selected_vars, collapse = ","),
    'for' = paste0(tolower(geography), ":", geography_query),
    key = key
  ))

  #Convert response to tibble
  census_data &lt;- response_to_tibble(response)

  #Convert numeric variables (JWAP & JWDP are time variables and not ordinary variables)
  regular_numeric &lt;- intersect(
    numeric_vars,
    c("AGEP", "GASP", "GRPIP", "JWMNP", "PWGTP")
  )

  census_data[regular_numeric] &lt;- lapply(
    census_data[regular_numeric],
    as.numeric
  )

  #Convert categorical variables to factors
  for (variable in categorical_vars) {

    value_labels &lt;- variable_info[[variable]]$values$item

    census_data[[variable]] &lt;- factor(
      census_data[[variable]],
      levels = names(value_labels),
      labels = unlist(value_labels)
    )
  }

  #Convert time variables to midpoint
  time_vars &lt;- intersect(
    numeric_vars,
    c("JWAP", "JWDP")
  )

  for (variable in time_vars) {

    #Get time interval labels 
    time_labels &lt;- variable_info[[variable]]$values$item

    #Match Census codes to time intervals
    intervals &lt;- sapply(
      census_data[[variable]],
      function(code) {
        if (is.na(code) || !code %in% names(time_labels)) {
          NA_character_
        } else {
          time_labels[[code]]
        }
      }
    )

    #Convert intervals to midpoint
    census_data[[variable]] &lt;- as.POSIXct(
      sapply(
        intervals,
        function(x) as.numeric(time_midpoint(x))
      ),
      origin = "1970-01-01",
      tz = "UTC"
    )
  }

  #Add census class
  class(census_data) &lt;- c("census", class(census_data))

  return(census_data)
  #End of get_census_data function
}

The following examples demonstrate how the time midpoint function converts Census time intervals into midpoint values and handles non-time values.

#Demonstrate Census time midpoint conversion
time_midpoint("11:00 p.m. to 11:04 p.m.")

[1] "0000-01-01 23:02:00 UTC"

time_midpoint("4:10 a.m. to 4:19 a.m.")

[1] "0000-01-01 04:14:30 UTC"

time_midpoint("Not a time value")

[1] NA



